// This file is the job package's database access layer. Fixed-shape statements
// are generated by sqlc (internal/store/queries/job.sql) and wrapped here to
// convert between Go and column types. The statements below stay hand-written:
//
//   - the job package's tests identify them by SQL text (exact or prefix) in
//     pgx query tracers and fault injectors, and sqlc prepends a "-- name:"
//     comment that would change that text;
//   - the dynamic ListJobs filter and the partition DDL have no fixed shape;
//   - the host disconnect statement is a CTE whose final SELECT sqlc reports
//     as ambiguous on host_id.
//
// The d argument is any pgx executor: a pool or a transaction. Callers pass
// s.Store.Pool, not s.Store.Queries, so that a store with a traced pool is used.

var errBigintRange = errors.New("value outside the column range")

func toInt64(v uint64) (int64, error) {
	if v > math.MaxInt64 {
		return 0, errBigintRange
	}
	return int64(v), nil
}

func toInt32(v uint32) (int32, error) {
	if v > math.MaxInt32 {
		return 0, errBigintRange
	}
	return int32(v), nil
}

func timestamptz(t time.Time) pgtype.Timestamptz { return pgtype.Timestamptz{Time: t, Valid: true} }

func optionalTimestamptz(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{}
	}
	return timestamptz(*t)
}

// Hand-written statements.

const jobColumns = "job_id,action,catalog_id,catalog_version,action_sha256,subject_id,reason,status,created_at,finished_at,policy_version"

func scanJob(row pgx.Row) (*v1.Job, error) {
	j := &v1.Job{Catalog: &v1.CatalogRef{}}
	var status int16
	var at time.Time
	var finished *time.Time
	err := row.Scan(&j.JobId, &j.Action, &j.Catalog.CatalogId, &j.Catalog.Version, &j.ActionSha256, &j.SubjectId, &j.Reason, &status, &at, &finished, &j.PolicyVersion)
	j.Status = v1.JobStatus(status)
	j.CreatedAt = timestamppb.New(at)
	if finished != nil {
		j.FinishedAt = timestamppb.New(*finished)
	}
	return j, err
}

func selectJob(ctx context.Context, d db.DBTX, id string) (*v1.Job, error) {
	return scanJob(d.QueryRow(ctx, "SELECT "+jobColumns+" FROM jobs WHERE job_id=$1", id))
}

// partition serializes partition creation and creates the month's tasks partition.
func partition(ctx context.Context, tx pgx.Tx, at time.Time) error {
	if err := db.New(tx).LockJobPartitionCreation(ctx); err != nil {
		return err
	}
	month := time.Date(at.UTC().Year(), at.UTC().Month(), 1, 0, 0, 0, 0, time.UTC)
	_, err := tx.Exec(ctx, fmt.Sprintf("CREATE TABLE IF NOT EXISTS tasks_%s PARTITION OF tasks FOR VALUES FROM ('%s') TO ('%s')", month.Format("200601"), month.Format(time.RFC3339), month.AddDate(0, 1, 0).Format(time.RFC3339)))
	return err
}

func readCancelRequested(ctx context.Context, d db.DBTX, id string) (bool, error) {
	var cancel bool
	err := d.QueryRow(ctx, "SELECT cancel_requested FROM jobs WHERE job_id=$1", id).Scan(&cancel)
	return cancel, err
}

func lockJobForFinish(ctx context.Context, tx pgx.Tx, id string) (cancelled bool, status int16, err error) {
	err = tx.QueryRow(ctx, "SELECT cancel_requested,status FROM jobs WHERE job_id=$1 FOR UPDATE", id).Scan(&cancelled, &status)
	return cancelled, status, err
}

func finishJobRow(ctx context.Context, tx pgx.Tx, id string, status int16) error {
	_, err := tx.Exec(ctx, "UPDATE jobs SET status=$2,finished_at=now() WHERE job_id=$1 AND status IN (1,2)", id, status)
	return err
}

// updateTaskTerminal writes a terminal result of a task that is still pending or running.
func updateTaskTerminal(ctx context.Context, d db.DBTX, jobID, taskID string, status int16, result []byte) (int64, error) {
	tag, err := d.Exec(ctx, "UPDATE tasks SET status=$3,result=$4,finished_at=now(),output_state='unavailable' WHERE job_id=$1 AND task_id=$2 AND status IN (1,2)", jobID, taskID, status, result)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}

// completeTask writes the terminal result and the output previews of a task event.
func completeTask(ctx context.Context, tx pgx.Tx, jobID, taskID string, status int16, result, stdoutPreview, stderrPreview, stdoutHash, stderrHash []byte, steps, stdoutSize, stderrSize int) error {
	_, err := tx.Exec(ctx, "UPDATE tasks SET status=$3,result=$4,finished_at=now(),stdout_preview=$5,stderr_preview=$6,stdout_sha256=$7,stderr_sha256=$8,step_count=$9,stdout_size=$10,stderr_size=$11 WHERE job_id=$1 AND task_id=$2 AND status IN (1,2)", jobID, taskID, status, result, stdoutPreview, stderrPreview, stdoutHash, stderrHash, steps, stdoutSize, stderrSize)
	return err
}

func updateOutputState(ctx context.Context, d db.DBTX, jobID, taskID string, stored bool, state string) error {
	_, err := d.Exec(ctx, "UPDATE tasks SET output_stored=$3,output_state=$4 WHERE job_id=$1 AND task_id=$2", jobID, taskID, stored, state)
	return err
}

// recoverTasks moves a lost instance's tasks from one status to another.
func recoverTasks(ctx context.Context, tx pgx.Tx, jobID string, from, to int16, result []byte) ([]string, error) {
	rows, err := tx.Query(ctx, "UPDATE tasks SET status=$3,result=$4,finished_at=now(),output_state='unavailable' WHERE job_id=$1 AND status=$2 RETURNING task_id", jobID, from, to, result)
	if err != nil {
		return nil, err
	}
	var ids []string
	for rows.Next() {
		var taskID string
		if err := rows.Scan(&taskID); err != nil {
			rows.Close()
			return nil, err
		}
		ids = append(ids, taskID)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	return ids, nil
}

func countDrainTasks(ctx context.Context, d db.DBTX, instanceID string) (int, error) {
	var tasks int
	err := d.QueryRow(ctx, "SELECT count(*) FROM tasks t JOIN hosts h ON h.host_id=t.host_id WHERE t.status IN (1,2) AND t.dispatched AND h.instance_id=$1 AND h.connection_id=t.connection_id", instanceID).Scan(&tasks)
	return tasks, err
}

type cancelTarget struct {
	id, host, connection string
	status               int16
}

// listCancelTargets returns the dispatched, unfinished tasks of a job.
func listCancelTargets(ctx context.Context, d db.DBTX, jobID string) ([]cancelTarget, error) {
	rows, err := d.Query(ctx, "SELECT task_id,host_id,COALESCE(connection_id,''),status FROM tasks WHERE job_id=$1 AND status IN (1,2) AND dispatched", jobID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var targets []cancelTarget
	for rows.Next() {
		var t cancelTarget
		if err := rows.Scan(&t.id, &t.host, &t.connection, &t.status); err != nil {
			return nil, err
		}
		targets = append(targets, t)
	}
	return targets, rows.Err()
}

type taskRef struct{ jobID, taskID string }

// errDisconnectScan marks a row scan failure of disconnectTasks.
var errDisconnectScan = errors.New("scan disconnected task")

// disconnectTasks marks the unfinished tasks of a connection offline and returns
// every task of that connection. A row scan failure is reported as errDisconnectScan.
func disconnectTasks(ctx context.Context, d db.DBTX, hostID, connectionID string, result []byte) ([]taskRef, error) {
	rows, err := d.Query(ctx, "WITH disconnected AS (UPDATE tasks SET status=6,result=$3,finished_at=now(),output_state='unavailable' WHERE host_id=$1 AND connection_id=$2 AND status IN (1,2) RETURNING job_id,task_id) SELECT job_id,task_id FROM tasks WHERE host_id=$1 AND connection_id=$2", hostID, connectionID, result)
	if err != nil {
		return nil, err
	}
	refs := []taskRef{}
	for rows.Next() {
		var p taskRef
		if err := rows.Scan(&p.jobID, &p.taskID); err != nil {
			rows.Close()
			return nil, errDisconnectScan
		}
		refs = append(refs, p)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	return refs, nil
}

// candidates returns up to limit job positions after the cursor. Only the
// filters that are set appear in the statement, so that it can use
// jobs_subject_created or jobs_created for ordering and the cursor.
func (f jobFilter) candidates(ctx context.Context, st *store.Store, after *jobCursor, limit int) ([]jobCursor, error) {
	where := []string{"TRUE"}
	args := []any{}
	add := func(condition string, value any) {
		args = append(args, value)
		where = append(where, fmt.Sprintf(condition, len(args)))
	}
	if f.subject != "" {
		add("subject_id=$%d", f.subject)
	}
	if f.action != "" {
		add("action=$%d", f.action)
	}
	if f.from != nil {
		add("created_at>=$%d", *f.from)
	}
	if f.to != nil {
		add("created_at<$%d", *f.to)
	}
	if len(f.statuses) > 0 {
		add("status=ANY($%d)", f.statuses)
	}
	if after != nil {
		args = append(args, after.created, after.id)
		where = append(where, fmt.Sprintf("(created_at,job_id)<($%d,$%d)", len(args)-1, len(args)))
	}
	args = append(args, limit)
	rows, err := st.Pool.Query(ctx, "SELECT job_id,created_at FROM jobs WHERE "+strings.Join(where, " AND ")+" ORDER BY created_at DESC,job_id DESC LIMIT $"+strconv.Itoa(len(args)), args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []jobCursor{}
	for rows.Next() {
		var c jobCursor
		if err := rows.Scan(&c.id, &c.created); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

// Generated statements.

func listActiveHosts(ctx context.Context, d db.DBTX) ([]host, error) {
	rows, err := db.New(d).ListActiveHosts(ctx)
	if err != nil {
		return nil, err
	}
	all := []host{}
	for _, r := range rows {
		h := host{ID: r.HostID, Name: r.Hostname, Connection: r.ConnectionID}
		if err := json.Unmarshal(r.AuthorizationLabels, &h.Labels); err != nil {
			return nil, err
		}
		if err := json.Unmarshal(r.ReportedLabels, &h.Reported); err != nil {
			return nil, err
		}
		all = append(all, h)
	}
	return all, nil
}

func countJobTasksByStatus(ctx context.Context, d db.DBTX, jobID string) ([]*v1.TaskCount, error) {
	rows, err := db.New(d).CountJobTasksByStatus(ctx, jobID)
	if err != nil {
		return nil, err
	}
	var counts []*v1.TaskCount
	for _, r := range rows {
		counts = append(counts, &v1.TaskCount{Status: v1.TaskStatus(r.Status), Count: uint64(r.Count)})
	}
	return counts, nil
}

func listJobTasks(ctx context.Context, d db.DBTX, jobID string) ([]*v1.Task, error) {
	rows, err := db.New(d).ListJobTasks(ctx, jobID)
	if err != nil {
		return nil, err
	}
	items := []*v1.Task{}
	for _, r := range rows {
		t := &v1.Task{Result: &v1.ExecutionResult{}, JobId: r.JobID, TaskId: r.TaskID, HostId: r.HostID, Hostname: r.Hostname, OutputStored: r.OutputStored, StepCount: uint32(r.StepCount)}
		if err := proto.Unmarshal(r.Result, t.Result); err != nil {
			return nil, err
		}
		if r.StartedAt.Valid {
			t.StartedAt = timestamppb.New(r.StartedAt.Time)
		}
		if r.FinishedAt.Valid {
			t.FinishedAt = timestamppb.New(r.FinishedAt.Time)
		}
		items = append(items, t)
	}
	return items, nil
}

