type newJob struct {
	id, subject, action, catalogID, reason, origin string
	at                                             time.Time
	definition, digest                             []byte
	catalogVersion                                 int64
	policyVersion                                  uint64
	status                                         v1.JobStatus
	batch, failures                                uint32
	finished                                       *time.Time
}

func insertJob(ctx context.Context, tx pgx.Tx, j newJob) error {
	policy, err := toInt64(j.policyVersion)
	if err != nil {
		return err
	}
	batch, err := toInt32(j.batch)
	if err != nil {
		return err
	}
	failures, err := toInt32(j.failures)
	if err != nil {
		return err
	}
	return db.New(tx).InsertJob(ctx, db.InsertJobParams{
		JobID: j.id, CreatedAt: timestamptz(j.at), SubjectID: j.subject, Action: j.action, ActionDefinition: j.definition,
		CatalogID: j.catalogID, CatalogVersion: j.catalogVersion, ActionSha256: j.digest, PolicyVersion: policy, Reason: j.reason,
		Status: int16(j.status), BatchSize: batch, MaxFailures: failures, FinishedAt: optionalTimestamptz(j.finished), OriginInstance: j.origin,
	})
}

func insertPendingTask(ctx context.Context, tx pgx.Tx, jobID, taskID string, at time.Time, h host, position int, result []byte) error {
	return db.New(tx).InsertPendingTask(ctx, db.InsertPendingTaskParams{JobID: jobID, TaskID: taskID, CreatedAt: timestamptz(at), HostID: h.ID, Hostname: h.Name, Position: int32(position), Result: result})
}

